#Requires -Version 7.0
. (Join-Path $PSScriptRoot 'TestHelpers.ps1');. (Join-Path $RepoRoot '.agents/skills/story-integrity/scripts/PromotionContracts.ps1')
$path=Join-Path $RepoRoot 'stories/a-crown-of-quiet-hours/promotion.json';$value=Get-Content $path -Raw|ConvertFrom-Json -Depth 100 -DateKind String;Assert-PromotionRecord $value 'a-crown-of-quiet-hours';Assert-Equal 'completed' $value.state 'Crown promotion is not completed.';Assert-Equal 31 @($value.deltaDispositions).Count 'Crown disposition count differs.';Assert-Equal 6 @($value.modifiedFiles).Count 'Crown modified-file count differs.';Assert-True (-not@($value.deltaDispositions|Where-Object{$_.disposition-cne'promote'}).Count) 'Crown has a non-promote disposition.'
foreach($item in $value.deltaDispositions){
 $parts=$item.target.Split('#',2);Assert-True ($parts.Count-eq2) "Promotion target lacks an entry anchor: $($item.target)";Assert-True ($parts[0] -cin @($value.modifiedFiles)) "Promotion target is outside declared universe files: $($item.target)";$content=Get-Content (Join-Path $RepoRoot $parts[0]) -Raw;$matched=$false
 foreach($heading in [regex]::Matches($content,'(?m)^## (?<name>.+?)\s*$')){$entryAnchor=($heading.Groups['name'].Value.ToLowerInvariant()-replace'[^a-z0-9 -]',''-replace'\s','-');if($entryAnchor-ceq$parts[1]){$start=$heading.Index;$next=$content.IndexOf("`n## ",$start+1);if($next-lt0){$next=$content.Length};$block=$content.Substring($start,$next-$start);Assert-True ($block.Contains('stories/a-crown-of-quiet-hours/05-story.md')) "Promotion entry lacks Crown provenance: $($item.target)";$matched=$true;break}}
 Assert-True $matched "Promotion target heading is missing: $($item.target)"
}
$invalid=($value|ConvertTo-Json -Depth 100|ConvertFrom-Json -Depth 100 -DateKind String);$invalid.deltaDispositions=@();$failed=$false;try{Assert-PromotionRecord $invalid 'a-crown-of-quiet-hours'}catch{$failed=$true};Assert-True $failed 'Missing dispositions were accepted.';'Promotion record tests passed.'